actions.action:
fa_zadal: f.fa_zadal, fa_zadal_meno: f.fa_zadal_meno,
fa_stav: f.fa_stav, fa_stav_label: f.fa_stav_label, fa_ceka_na: f.fa_ceka_na,
fa_dodavatel: f.fa_dodavatel, fa_cislo: f.fa_cislo, fa_suma: f.fa_suma;

def u = loggedUser()

change fa_zadal value { [u.id] }
change fa_zadal_meno value { kto(u) }
change fa_stav value { "koncept" }
change fa_stav_label value { "koncept" }
// Rozpisana faktura lezi u toho, kto ju zacal - notifikacia sa neposiela,
// preto sa `po_zmene_stavu` nevola: clovek nema dostat mail o tom, ze si
// prave zalozil fakturu.
change fa_ceka_na value { kto(u) }
changeCaseProperty("color").about { farba("koncept") }
// Nazov sa nikde nezadava rucne - polozka menu ma vypnute `enable_case_title`,
// takze "+" zaklada case rovno a nazov vznikne tu.
changeCaseProperty("title").about { nazov(fa_dodavatel, fa_cislo, fa_suma, "koncept") }

document.function:
{ ->
    // Hranica dvoch urovni schvalenia, v EUR s DPH: do limitu vratane staci
    // stredisko, nad limit schvaluje aj riaditel.
    //
    // Cita sa z konfiguracneho casu (`nastavenia/sc_nastavenia`), aby sa dala
    // zmenit v appke a nie novou verziou siete. Ked konfiguracia neexistuje
    // alebo je prazdna, plati zabudovanych 1000 - appka musi fungovat aj
    // v instancii, kde konfiguracnu siet nikto nenaimportoval.
    def cfg = najnovsiCase("nastavenia/sc_nastavenia")
    def v = cfg?.dataSet?.get("sc_limit")?.value
    if (v == null) return 1000.0d
    double d = (v as Number).doubleValue()
    return d > 0 ? d : 1000.0d
}

{ def u ->
    // Nie `u?.fullName` - `?.` chrani pred null, nie pred chybajucou property,
    // a na chybajucej vyhodi MissingPropertyException uprostred akcie.
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ def kod ->
    // Farba casu je to jedine, co je v zozname vidno bez citania - obarvi sa
    // ju ikona riadku. Paleta enginu: red|orange|yellow|green|teal|cyan|blue|
    // indigo|purple|pink|brown|grey.
    def m = ["koncept"       : "grey",
             "na_schvalenie" : "blue",
             "u_riaditela"   : "indigo",
             "na_zauctovanie": "teal",
             "zauctovana"    : "green",
             "vratena"       : "orange",
             "zamietnuta"    : "red"]
    return m[kod as String] ?: "grey"
}

{ def fa_suma ->
    def v = fa_suma.value
    if (v == null) return "suma nevyplnená"
    // Locale.US zamerne: formatovanie sa deje na serveri a nema zavisiet od
    // toho, aky locale ma nahodou JVM. Oddelovac je preto bodka.
    return String.format(java.util.Locale.US, "%.2f", (v as Number).doubleValue()) + " €"
}

{ def fa_dodavatel, def fa_cislo, def fa_suma, def stavKod ->
    // BEZ STAVU. `Case.title` je v engine `String`, takze sa neda prelozit -
    // slovensky stav v nazve by bol v anglickom portali jediny slovensky text
    // v kazdom zozname. Stav nesie pole `fa_stav_label`, ktore je
    // `enumeration_map` a teda prelozene, a je v kazdom zobrazeni ako stlpec.
    //
    // Argument `stavKod` zostava v signature zamerne: volania su na siedmich
    // miestach a az sa `Case.title` prelozit da, netreba ich prepisovat.
    def dod = ((fa_dodavatel.value ?: "") as String).trim()
    def cis = ((fa_cislo.value ?: "") as String).trim()
    // Kym nie je dodavatel, nesie nazov CISLO PRIPADU (`visualId`) - je
    // jazykovo neutralne a v zozname sa da podla neho odkazat. "—" by bolo
    // nerozlisitelne od kazdej inej rozpisanej faktury.
    def co = dod ?: ((useCase.visualId ?: "?") as String)
    if (cis) co = co + " č. " + cis
    def suma = fa_suma.value
    if (suma != null && (suma as Number).doubleValue() > 0) {
        co = co + " · " + suma_slovom(fa_suma)
    }
    return co
}

{ def fa_historia, def text ->
    // Poznamka sa medzi urovnami schvalenia prepisuje - historia je to jedine,
    // co drzi, co si stredisko, riaditel a uctovnik medzi sebou vymenili.
    def ts = java.time.LocalDateTime.now()
            .format(java.time.format.DateTimeFormatter.ofPattern("d.M.yyyy HH:mm"))
    def log = (fa_historia.value ?: "") as String
    def riadok = ts + "  " + (text as String)
    change fa_historia value { log ? log + "\n" + riadok : riadok }
}

{ def fa_suma ->
    def v = fa_suma.value
    if (v == null) return false
    return (v as Number).doubleValue() > limit_riaditela()
}

{ def fa_suma, def fa_kontrola ->
    // Zive upozornenie pri pisani sumy. Vracia true, ak je co povedat - podla
    // toho akcia pole odkryje alebo skryje, aby na formulari netrcal prazdny
    // ramik s nadpisom, ktory vyzera ako ovladaci prvok a nie je nim.
    def v = fa_suma.value
    if (v == null) {
        change fa_kontrola value { "" }
        return false
    }
    def d = (v as Number).doubleValue()
    if (d <= 0) {
        change fa_kontrola value { "Suma musí byť väčšia ako nula – takto sa faktúra podať nedá." }
        return true
    }
    if (d > limit_riaditela()) {
        change fa_kontrola value {
            "Nad " + String.format(java.util.Locale.US, "%.0f", limit_riaditela()) +
                    " € schvaľuje po stredisku ešte riaditeľ."
        }
        return true
    }
    change fa_kontrola value { "" }
    return false
}

{ def pole, def hodnota, def popis, def doplnene, def rozdiely ->
    // Nacitanie z prilohy NIKDY neprepise to, co clovek napisal - rozdiel len
    // ohlasi. Inak by jedno kliknutie ticho zmenilo sumu, ktoru niekto prave
    // opravoval podla papiera, a nikto by nevedel, ze sa to stalo.
    if (hodnota == null) return
    def nova = (hodnota as String).trim()
    if (!nova) return
    def teraz = pole.value
    // POZOR: `number` pole bez vyplnenej hodnoty nevracia null, ale 0.0.
    // Bez tejto vetvy by sa suma z prilohy nikdy nedoplnila - pole by sa
    // tvarilo ako vyplnene nulou a akcia by hlasila "rozdiel" namiesto toho,
    // aby sumu zapisala. Odhalil to az akceptacny test.
    boolean nulove = (teraz instanceof Number) && ((teraz as Number).doubleValue() == 0.0d)
    def stara = (teraz == null || nulove) ? "" : (teraz as String).trim()
    if (!stara) {
        change pole value { hodnota }
        doplnene << (popis as String)
    } else if (stara != nova) {
        rozdiely << ((popis as String) + ": v prílohe „" + nova + "“, vo formulári „" + stara + "“")
    }
}

{ def kod ->
    def m = ["xml" : "XML e-faktúra (čítané)",
             "text": "PDF, textová vrstva (čítané)",
             "ocr" : "OCR skenu (odhad)",
             "nic" : "nepodarilo sa"]
    return m[(kod ?: "nic") as String] ?: (kod as String)
}

{ def fa_stredisko, def fa_zadal, def fa_schvalovatelia, def fa_historia ->
    // Kto smie schvalit TUTO fakturu: uzivatelia s rolou daneho strediska,
    // bez toho, kto ju zapisal (styri oci uz na vstupe, nie az pri odmietnuti).
    //
    // Kaskada je zamerna a kazdy stupen sa zapise do priebehu - inak by faktura
    // v stredisku, ktore nikoho nema, cakala navzdy a nikto by nevedel preco.
    def kod = ((fa_stredisko.value ?: "") as String).trim()
    def zadal = (userIdsOf(fa_zadal.value) ?: []).collect { it as String }
    def bezZadavatela = { List ids -> (ids ?: []).collect { it as String } - zadal }

    def kandidati = bezZadavatela(usersWithRoleAll("schv_" + kod))
    def preco = null
    if (!kandidati) {
        kandidati = bezZadavatela(usersWithRoleAll("schvalovatel"))
        preco = "stredisko nemá vlastného schvaľovateľa, ide to všetkým schvaľovateľom"
    }
    if (!kandidati) {
        kandidati = bezZadavatela(usersWithRoleAll("riaditel"))
        preco = "nikto okrem riaditeľa nemôže túto faktúru schváliť"
    }
    change fa_schvalovatelia value { kandidati }
    if (preco) {
        zapis_historie(fa_historia, "smerovanie: " + preco)
    }
    return kandidati
}

{ def kod, def fa_zadal, def fa_schvalovatelia ->
    // Kto je na rade. Vracia ID uzivatelov, nie rolu ako slovo - do
    // `fa_ceka_na` patria mena (vid komentar pri tom poli).
    def k = ((kod ?: "") as String)
    if (k == "na_schvalenie") return userIdsOf(fa_schvalovatelia.value)
    if (k == "u_riaditela") return usersWithRoleAll("riaditel")
    if (k == "na_zauctovanie") return usersWithRoleAll("uctovnik")
    if (k == "vratena" || k == "koncept") return userIdsOf(fa_zadal.value)
    // zauctovana, zamietnuta - uzavrete, necaka sa na nikoho
    return []
}

{ def kod, def fa_ceka_na, def fa_zadal, def fa_schvalovatelia, def fa_historia,
  def fa_dodavatel, def fa_cislo, def fa_suma, def fa_stredisko ->
    // Jedno miesto pre dve veci, ktore sa musia stat pri KAZDEJ zmene stavu:
    // zapisat, u koho faktura lezi, a upozornit toho, kto je na rade. Kym to
    // bolo rozpisane po styroch prechodoch, jeden z nich to vzdy zabudol.
    def k = ((kod ?: "") as String)
    def ids = cakajuci(k, fa_zadal, fa_schvalovatelia)
    def mena = menaUzivatelov(ids)
    change fa_ceka_na value { mena ? mena.join(", ") : "—" }

    // Uzavretu fakturu uz nikto nedrzi, ale zadavatel ma vediet, ako skoncila.
    def komu = ids ?: ((k in ["zauctovana", "zamietnuta"]) ? userIdsOf(fa_zadal.value) : [])
    if (!komu) return 0

    def dod = ((fa_dodavatel.value ?: "") as String).trim()
    def cis = ((fa_cislo.value ?: "") as String).trim()
    def popis = (dod ?: "faktúra") + (cis ? " č. " + cis : "")

    def telo = new StringBuilder()
    telo.append(veta_o_stave(k)).append("\n\n")
    telo.append("Faktúra:   ").append(popis).append("\n")
    telo.append("Suma:      ").append(suma_slovom(fa_suma)).append("\n")
    telo.append("Stredisko: ").append(((fa_stredisko.value ?: "-") as String)).append("\n")
    telo.append("\nPortál eTask → Objednávky a faktúry → Faktúry.\n")

    def poslane = notifikuj(komu, popis + " – " + veta_o_stave(k), telo.toString())
    if (poslane > 0) {
        zapis_historie(fa_historia, "upozornenie e-mailom: " + poslane + "×")
    }
    return poslane
}

{ def fa_objednavka_vyber ->
    // Schvalene objednavky, na ktore sa da fakturovat. Filtruje sa V GROOVY:
    // `findCases { it.dataSet... }` nad Mongom nefunguje (to je iny mechanizmus
    // nez dataSet dopyt v Elasticu).
    def zivé = findCases { it.processIdentifier.eq("schvalovanie/objednavky/ob_objednavka") }
    def moznosti = [:]
    (zivé ?: []).each { c ->
        def stav = ((c.dataSet["ob_stav"]?.value ?: "") as String)
        if (!(stav in ["na_objednanie", "objednana"])) return
        def cislo = ((c.dataSet["ob_cislo"]?.value ?: "") as String).trim()
        def dod = ((c.dataSet["ob_dodavatel"]?.value ?: "") as String).trim()
        def suma = c.dataSet["ob_suma"]?.value
        def popis = (cislo ?: "bez čísla") + " · " + (dod ?: "?") +
                (suma == null ? "" : (" · " + String.format(java.util.Locale.US, "%.2f",
                        (suma as Number).doubleValue()) + " €"))
        // Kluc je id casu - 24 hex znakov, teda ziadna bodka ani dolar, ktore
        // Mongo v nazvoch poli zakazuje (C17).
        moznosti.put(c.stringId as String, popis)
    }
    change fa_objednavka_vyber options { moznosti }
    return moznosti.size()
}

{ def fa_objednavka_vyber, def fa_objednavka, def fa_dodavatel, def fa_suma,
  def fa_objednavka_info ->
    def id = ((fa_objednavka_vyber.value ?: "") as String).trim()
    if (!id) {
        change fa_objednavka_info value { "" }
        return
    }
    // `findCase { it.stringId.eq(id) }` vracia vzdy null - `Case` v Mongu pole
    // `stringId` nema. Ide sa cez ObjectId (B13).
    def c = findCase { it._id.eq(new org.bson.types.ObjectId(id)) }
    if (c == null) {
        change fa_objednavka_info value { "Objednávka sa nenašla - vyberte ju znova." }
        return
    }
    def cislo = ((c.dataSet["ob_cislo"]?.value ?: "") as String).trim()
    def dod = ((c.dataSet["ob_dodavatel"]?.value ?: "") as String).trim()
    def objSuma = c.dataSet["ob_suma"]?.value
    def predmet = ((c.dataSet["ob_predmet"]?.value ?: "") as String).trim()

    if (cislo) change fa_objednavka value { cislo }
    if (dod && !((fa_dodavatel.value ?: "") as String).trim()) {
        change fa_dodavatel value { dod }
    }

    def text = new StringBuilder()
    text.append(predmet ?: "objednávka")
    if (objSuma != null) {
        text.append(" · objednané za ")
                .append(String.format(java.util.Locale.US, "%.2f", (objSuma as Number).doubleValue()))
                .append(" €")
    }
    // Rozdiel je to jedine, co na fakturovani podla objednavky naozaj zalezi:
    // schvalovatel ma vediet, ze dodavatel fakturuje viac, nez bolo schvalene.
    def faSuma = fa_suma.value
    if (objSuma != null && faSuma != null) {
        double rozdiel = (faSuma as Number).doubleValue() - (objSuma as Number).doubleValue()
        if (rozdiel > 0.005d) {
            text.append(" · POZOR: fakturuje o ")
                    .append(String.format(java.util.Locale.US, "%.2f", rozdiel))
                    .append(" € viac, než bolo objednané")
        }
    }
    change fa_objednavka_info value { text.toString() }
}

{ def fa_zadal, def rola ->
    // STVORI OCI. `userIdsOf` je primitiv delegata - id z userList pola sa
    // nikdy netahaju rucne, `u?._id` zhodi celu akciu.
    def zadal = (userIdsOf(fa_zadal.value) ?: []).collect { it as String }
    def ja = loggedUser().id as String
    if (zadal.contains(ja)) {
        throw new java.lang.IllegalStateException(
                "Faktúru, ktorú ste zapísali, nemôžete schváliť ako " + (rola as String) +
                        ". Nech ju schváli niekto iný.")
    }
}

actions.action:
fa_suma: f.fa_suma, fa_kontrola: f.fa_kontrola;
boolean varuj = prepocet(fa_suma, fa_kontrola)
make fa_kontrola, visible on transitions when { varuj }
make fa_kontrola, hidden  on transitions when { !varuj }

fa_skan: f.fa_skan, fa_dodavatel: f.fa_dodavatel, fa_cislo: f.fa_cislo,
fa_suma: f.fa_suma, fa_datum_splatnosti: f.fa_datum_splatnosti,
fa_datum_vystavenia: f.fa_datum_vystavenia, fa_ico: f.fa_ico, fa_iban: f.fa_iban,
fa_zdroj: f.fa_zdroj, fa_nacitanie: f.fa_nacitanie, fa_kontrola: f.fa_kontrola;

// `precitajFakturu` je primitiv delegata (vrstva 2): XML e-fakturu precita,
// PDF s textovou vrstvou tiez, sken prezenie OCR. Toto je presne ten typ
// prace, ktora sa v Petriflow vyjadrit neda - otvorit subor a spustit proces.
// `useCase.stringId` treba na dopocitanie cesty k prilohe.
def r = precitajFakturu(fa_skan, useCase.stringId)

if (r.chyba) {
    change fa_nacitanie value { r.chyba as String }
    change fa_zdroj value { "" }
} else {
    def doplnene = []
    def rozdiely = []

    dopln_ak_prazdne(fa_dodavatel, r.dodavatel, "dodávateľ", doplnene, rozdiely)
    dopln_ak_prazdne(fa_cislo, r.cislo, "číslo faktúry", doplnene, rozdiely)
    dopln_ak_prazdne(fa_suma, r.suma, "suma", doplnene, rozdiely)
    dopln_ak_prazdne(fa_datum_splatnosti, r.splatnost, "splatnosť", doplnene, rozdiely)
    dopln_ak_prazdne(fa_datum_vystavenia, r.vystavenie, "dátum vystavenia", doplnene, rozdiely)
    dopln_ak_prazdne(fa_ico, r.ico, "IČO", doplnene, rozdiely)
    dopln_ak_prazdne(fa_iban, r.iban, "IBAN", doplnene, rozdiely)

    def sprava = new StringBuilder()
    sprava.append("Zdroj: ").append(zdroj_slovom(r.zdroj))
    if (doplnene) sprava.append(". Doplnené: ").append(doplnene.join(", "))
    if (r.nedocitane) sprava.append(". Neprečítané: ").append((r.nedocitane as List).join(", "))
    if (rozdiely) sprava.append(". POZOR, nesúhlasí – ").append(rozdiely.join("; "))
    if (r.poznamka) sprava.append(". ").append(r.poznamka as String)
    if (!doplnene && !rozdiely && !r.nedocitane) sprava.append(". Nič nové som nenašiel.")

    change fa_nacitanie value { sprava.toString() }
    change fa_zdroj value { zdroj_slovom(r.zdroj) }

    // Suma sa mohla zmenit, a jej `set` udalost sa pri zapise z akcie nespusti -
    // upozornenie na limit teda treba prepocitat rucne.
    boolean varuj = prepocet(fa_suma, fa_kontrola)
    make fa_kontrola, visible on transitions when { varuj }
    make fa_kontrola, hidden  on transitions when { !varuj }
}

fa_suma: f.fa_suma, fa_datum_splatnosti: f.fa_datum_splatnosti;

// Jedine miesto, ktore zapis naozaj zastavi. Vyhodenie vynimky v phase="pre"
// zrusi dokoncenie prechodu, takze token zostane v p_koncept. `required`
// overi len to, ze pole nie je prazdne. Odmietnutie vracia HTTP 200 a dovod
// v tele ako `error` - test na stavovy kod ho prehliadne.
def v = fa_suma.value
if (v == null || (v as Number).doubleValue() <= 0) {
    throw new java.lang.IllegalStateException("Suma s DPH musí byť väčšia ako nula.")
}
if (fa_datum_splatnosti.value == null) {
    throw new java.lang.IllegalStateException("Vyplňte dátum splatnosti.")
}

fa_stav: f.fa_stav, fa_stav_label: f.fa_stav_label, fa_zapisane_o: f.fa_zapisane_o,
fa_kontrola: f.fa_kontrola, fa_historia: f.fa_historia, fa_suma: f.fa_suma,
fa_dodavatel: f.fa_dodavatel, fa_cislo: f.fa_cislo, fa_zdroj: f.fa_zdroj,
fa_stredisko: f.fa_stredisko, fa_zadal: f.fa_zadal, fa_ceka_na: f.fa_ceka_na,
fa_schvalovatelia: f.fa_schvalovatelia;

def opakovane = (((fa_stav.value ?: "") as String) == "vratena")

// Kto smie tuto fakturu schvalit. Prepocitava sa pri KAZDOM podani - po vrateni
// sa stredisko moze zmenit a s nim aj schvalovatel.
def komu = schvalovatelia_strediska(fa_stredisko, fa_zadal, fa_schvalovatelia, fa_historia)

change fa_stav value { "na_schvalenie" }
change fa_stav_label value { "na_schvalenie" }
changeCaseProperty("color").about { farba("na_schvalenie") }
change fa_zapisane_o value { java.time.LocalDateTime.now() }
change fa_kontrola value { "" }
zapis_historie(fa_historia, (opakovane ? "doplnené a podané znova: " : "zapísaná: ") +
        suma_slovom(fa_suma) + (nad_limit(fa_suma) ? " (nad limit, pôjde aj riaditeľovi)" : "") +
        (((fa_zdroj.value ?: "") as String) ? ", údaje z: " + fa_zdroj.value : ""))
changeCaseProperty("title").about { nazov(fa_dodavatel, fa_cislo, fa_suma, "na_schvalenie") }
po_zmene_stavu("na_schvalenie", fa_ceka_na, fa_zadal, fa_schvalovatelia, fa_historia,
        fa_dodavatel, fa_cislo, fa_suma, fa_stredisko)

fa_objednavka_vyber: f.fa_objednavka_vyber;

// Moznosti sa stavaju pri OTVORENI ulohy, nie pri zalozeni pripadu: zoznam
// schvalenych objednavok sa meni kazdy den a `change options` v udalosti
// `create` pripadu sa aj tak neuchova (B11).
objednavky_options(fa_objednavka_vyber)

fa_rozhodnutie: f.fa_rozhodnutie, fa_poznamka: f.fa_poznamka, fa_suma: f.fa_suma,
fa_zadal: f.fa_zadal,
fa_to_riaditel: f.fa_to_riaditel, fa_to_zauctovanie: f.fa_to_zauctovanie,
fa_to_koncept: f.fa_to_koncept, fa_to_uzavreta: f.fa_to_uzavreta;

// STVORI OCI. Je to tu a nie v udalosti `assign`, hoci tam by to zabralo
// skor: vynimka z akcie v `assign` vracia HOLE HTTP 500 bez spravy, kym tu
// vrati engine HTTP 200 a vetu v tele ako `error` (ENGINE_ISSUES E18).
nie_vlastnu(fa_zadal, "schvaľovateľ strediska")

// SMEROVANIE MUSI BYT V phase="pre". Engine vyhodnoti nasobnosti variable
// arcov po `pre` a pred `post`; keby sa flagy nastavili v `post`, token by sa
// pohyboval s povodnymi nulami a nevystrelil by ani jeden arc - case by ostal
// bez tokenu (C4).
def volba = ((fa_rozhodnutie.value ?: "") as String).trim()

if (!volba) {
    throw new java.lang.IllegalStateException(
            "Vyberte, či faktúru schvaľujete, vraciate na doplnenie alebo zamietate.")
}
if (!(volba in ["schvalit", "vratit", "zamietnut"])) {
    // Bez tohto by nezname rozhodnutie nechalo vsetky flagy na nule a token by
    // sa z p_na_schvalenie stratil bez toho, aby kdekolvek pribudol.
    throw new java.lang.IllegalStateException("Neznáme rozhodnutie: " + volba)
}
if (volba != "schvalit" && !((fa_poznamka.value ?: "") as String).trim()) {
    // Povinne je to len pri vrateni a zamietnuti, takze sa to neda vyjadrit
    // `required` na dataRefe - ten plati pre vsetky tri moznosti naraz.
    throw new java.lang.IllegalStateException(
            "Napíšte dôvod - zadávateľ inak nevie, čo s faktúrou robiť.")
}

boolean naRiaditela = (volba == "schvalit" && nad_limit(fa_suma))

change fa_to_riaditel    value { (naRiaditela ? 1 : 0) as Double }
change fa_to_zauctovanie value { ((volba == "schvalit" && !naRiaditela) ? 1 : 0) as Double }
