def meno = kto(loggedUser())
def pozn = ((fa_poznamka.value ?: "") as String).trim()

def kod
if (volba == "vratit") {
    kod = "vratena"
    zapis_historie(fa_historia, "vrátené na doplnenie (" + meno + "): " + pozn)
} else if (volba == "zamietnut") {
    kod = "zamietnuta"
    zapis_historie(fa_historia, "zamietnuté strediskom (" + meno + "): " + pozn)
} else {
    change fa_schvalil_stredisko value { meno }
    if (nad_limit(fa_suma)) {
        kod = "u_riaditela"
        zapis_historie(fa_historia, "schválené strediskom (" + meno + "), suma " +
                suma_slovom(fa_suma) + " je nad limit – ide riaditeľovi" +
                (pozn ? ": " + pozn : ""))
    } else {
        kod = "na_zauctovanie"
        // Kedy bola faktura schvalena, ma zmysel az vtedy, ked je schvalovanie
        // dokoncene - pri postupe k riaditelovi este nie je.
        change fa_schvalene_o value { java.time.LocalDateTime.now() }
        zapis_historie(fa_historia, "schválené strediskom (" + meno + ")" +
                (pozn ? ": " + pozn : ""))
    }
}

change fa_stav value { kod }
change fa_stav_label value { kod }
changeCaseProperty("color").about { farba(kod) }
// Vynulovat vyber, inak by pri dalsom kole (po vrateni a opatovnom podani)
